// ═══════════════════════════════════════════════════════════
// Product FAQ Data — AI-Optimized Q&A for each product
// Structured for Schema.org FAQPage JSON-LD markup
// ═══════════════════════════════════════════════════════════

export interface FaqItem {
  q: Record<string, string>;
  a: Record<string, string>;
}

// Helper: get localized text, fallback to en
function t(record: Record<string, string>, locale: string): string {
  return record[locale] || record.en || '';
}

export function getProductFaqs(slug: string, locale: string): Array<{q: string; a: string}> {
  const faqs = productFaqs[slug];
  if (!faqs) return [];
  return faqs.map((f) => ({q: t(f.q, locale), a: t(f.a, locale)}));
}

